def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 3]

    for r, c in points:
        # Top stripe
        if r - 2 >= 0:
            for x in range(max(0, c - 2), min(w, c + 3)):
                out[r - 2][x] = 5

        # Sides and the short stripe through the flag's center
        for y in (r - 1, r, r + 1):
            if 0 <= y < h:
                for x in (c - 2, c + 2):
                    if 0 <= x < w:
                        out[y][x] = 2
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = 3

        # Bottom stripe, with the rest of that row colored 2
        y = r + 2
        if 0 <= y < h:
            for x in range(w):
                out[y][x] = 2
            for x in range(max(0, c - 2), min(w, c + 3)):
                out[y][x] = 8

    return out
